(function(){"use strict";function n(n,t,i){function r(n){let t=new Date,i=n.split(":");return t.setHours(i[0],i[1],i[2]),t.setSeconds(0),t.setMilliseconds(0),t}n.configurations=[];n.printerConfig=!1;n.initialLoad=()=>{try{n.configurations=[];t.getData("get","/ConfigTpv/Get").then(t=>{if(t.code=="1"){let i=JSON.parse(t.payload);for(const t of i)n.configurations.push({idConfigTpv:t.idConfigTpv,codigo:t.codigo,descripcion:t.descripcion,horaInicio:r(t.horaInicio),horaFin:r(t.horaFin),estado:t.estado})}else i.toastr("warning",t.message)},n=>{console.log(n)});t.getData("get","/ConfigPrinter/Get").then(t=>{if(t.code=="1"){let i=JSON.parse(t.payload);n.printerConfig=i[0].estado}else console.log(t.message)},n=>{console.log(n)})}catch(u){console.log(u)}};n.initialLoad();n.validateTime=(n,t)=>n==t?!1:n>t?!1:t>n?!0:void 0;n.save=r=>{try{let u=$("#horaInicio-"+r.codigo).val(),f=$("#horaFin-"+r.codigo).val();if(!n.validateTime(u,f)){i.toastr("warning","Horario incorrecto: "+r.descripcion);return}if(!u){i.toastr("warning","Seleccione una hora de inicio para el servicio de: "+r.descripcion);return}if(!f){i.toastr("warning","Seleccione una hora de fin para el servicio de: "+r.descripcion);return}let e="",o="",s={idConfigTpv:r.idConfigTpv,codigo:r.codigo,descripcion:r.descripcion,horaInicio:u,horaFin:f,estado:r.estado};r.idConfigTpv>0?(e="put",o="/ConfigTpv/Put?json="+JSON.stringify(s)):(e="post",o="/ConfigTpv/Post?json="+JSON.stringify(s));t.getData(e,o).then(t=>{t.code=="1"?(n.initialLoad(),i.toastr("success",t.message)):i.toastr("warning",t.message)},n=>{console.log(n)})}catch(u){console.log(u)}};n.put=r=>{try{t.getData("put","/ConfigTpv/Put?json="+JSON.stringify(r)).then(t=>{t.code=="1"?(n.initialLoad(),i.toastr("success",t.message)):i.toastr("warning",t.message)},n=>{console.log(n)})}catch(u){console.log(u)}};n.askToDelete=t=>{t.idConfigTpv>0?Swal.fire({title:"¿Está seguro/a de eliminar este servicio?",text:"¡No podrás revertir esto!",icon:"warning",showCancelButton:!0,confirmButtonColor:"#3085d6",cancelButtonColor:"#d33",confirmButtonText:"Si!",cancelButtonText:"No",allowOutsideClick:!1}).then(i=>{i.value&&n.delete(t)}):i.toastr("warning","Aun no se ha guardado este servicio!")};n.delete=r=>{try{t.getData("delete","/ConfigTpv/Delete?id="+r.idConfigTpv).then(t=>{t.code=="1"?(n.initialLoad(),i.toastr("success",t.message)):i.toastr("warning",t.message)},n=>{console.log(n)})}catch(u){console.log(u)}};n.saveConfigPrinter=()=>{try{let r="",u="";r="post";u="/ConfigPrinter/Post?estado="+n.printerConfig;t.getData(r,u).then(t=>{t.code=="1"?(n.initialLoad(),i.toastr("success",t.message)):i.toastr("warning",t.message)},n=>{console.log(n)})}catch(r){console.log(r)}}}app.controller("configTpvCtrl",n);n.$inject=["$scope","mainService","toastService"]})(window.angular);